LOGS = ["INFO"] * 90 + ["WARNING"] * 6 + ["ERROR"] * 3 + ["CRITICAL"] * 1
SEVERITY_ORDER = ["INFO", "WARNING", "ERROR", "CRITICAL"]
ERROR_BUDGET = 0.01  # 99% SLO

def count_by_severity(logs):
    counts = {sev: 0 for sev in SEVERITY_ORDER}
    for entry in logs:
        if entry in counts:
            counts[entry] += 1
    return counts

def error_ratio(counts):
    total = sum(counts.values())
    if total == 0:
        return 0.0
    return (counts["ERROR"] + counts["CRITICAL"]) / total

def burn_rate(ratio, error_budget):
    return ratio / error_budget

counts = count_by_severity(LOGS)
for sev in SEVERITY_ORDER:
    print(f"{sev}: {counts[sev]}")
ratio = error_ratio(counts)
print(f"error ratio: {ratio * 100:.2f}%")
br = burn_rate(ratio, ERROR_BUDGET)
if br > 1:
    print(f"burn rate: {br:.1f}x -> PAGE")
else:
    print(f"burn rate: {br:.1f}x -> OK")
